workspace_guide: {
    title: "Cos'è un Workspace e come iniziare",
    p1: "In VanillaDesk <b>non esistono server cloud o account remoti</b>: tutti i tuoi dati risiedono esclusivamente sul tuo computer.",
    p2: "Un <b>Workspace</b> è semplicemente una <b>cartella sul tuo disco fisso</b> (ad esempio nella cartella <i>Documenti</i> o sul <i>Desktop</i>) che conterrà in modo trasparente e permanente le tue note, i database e gli allegati.",
    box_title: "Cosa fare adesso:",
    step1: "Clicca su <b>\"Procedi e Scegli Cartella\"</b> qui sotto.",
    step2: "Nella finestra di sistema, seleziona una cartella dedicata (ti consigliamo di crearne una nuova vuota, ad esempio <i>\"Note Personali\"</i>).",
    step3: "Quando il browser ti chiede la conferma dei permessi per salvare i file, clicca su <b>\"Visualizza file\"</b> o <b>\"Salva modifiche\"</b>.",
    btn_confirm: "Procedi e Scegli Cartella",
    save_title: "Salva Workspace su Disco",
    save_p1: "I tuoi dati sono attualmente memorizzati in sicurezza nella memoria locale (RAM). Per renderli permanenti, seleziona la cartella di lavoro sul tuo PC.",
    save_box_title: "Come procedere:",
    save_step_existing: "<b>Se avevi già un Workspace:</b> seleziona la tua cartella di lavoro abituale per aggiornarla con le modifiche correnti.",
    save_step_new: "<b>Se è un nuovo archivio:</b> seleziona una cartella dedicata sul tuo disco fisso.",
    save_step_permissions: "Quando il browser ti chiede la conferma dei permessi, clicca su <b>\"Visualizza file\"</b> o <b>\"Salva modifiche\"</b>.",
    btn_save_confirm: "Scegli Cartella e Salva",
    confirm_update_existing_ws: "La cartella selezionata contiene già un Workspace VanillaDesk.\n\nVuoi collegarla e salvare qui le modifiche correnti della sessione?",
    confirm_folder_not_empty: "Attenzione: La cartella selezionata contiene altri file.\nL'applicazione salverà le note e i database al suo interno. Vuoi procedere?"
},
modpack_guide: {
    title: "Cos'è un Modpack e come funziona",
    p1: "Un <b>Modpack</b> è un pacchetto autonomo e condivisibile in formato JSON che racchiude una nota completa insieme a tutti i suoi componenti avanzati (Database relazionali, Bacheche Kanban, formule, grafici e pulsanti Macro).",
    p2: "L'installazione è <b>completamente sicura e non distruttiva</b>: verrà creata una nuova nota nel tuo Workspace e tutti gli identificatori dei database verranno rigenerati per non sovrascrivere mai i tuoi dati esistenti.",
    box_title: "Cosa fare adesso:",
    step1: "Clicca su <b>\"Procedi e Scegli File\"</b> qui sotto.",
    step2: "Seleziona il file <code>.json</code> del Modpack salvato sul tuo computer.",
    step3: "Conferma l'anteprima del pacchetto per inserirlo istantaneamente nel tuo spazio di lavoro.",
    btn_confirm: "Procedi e Scegli File"
},
