workspace_guide: {
    title: "Qué es un Espacio de Trabajo y cómo empezar",
    p1: "En VanillaDesk <b>no existen servidores en la nube ni cuentas remotas</b>: todos tus datos residen exclusivamente en tu ordenador.",
    p2: "Un <b>Espacio de Trabajo</b> es simplemente una <b>carpeta en tu disco duro</b> (por ejemplo en la carpeta <i>Documentos</i> o en el <i>Escritorio</i>) que contendrá de forma transparente y permanente tus notas, bases de datos y adjuntos.",
    box_title: "Qué hacer ahora:",
    step1: "Haz clic en <b>\"Continuar y Elegir Carpeta\"</b> a continuación.",
    step2: "En la ventana del sistema, selecciona una carpeta dedicada (te recomendamos crear una nueva vacía, por ejemplo <i>\"Notas Personales\"</i>).",
    step3: "Cuando el navegador solicite confirmar los permisos para guardar archivos, haz clic en <b>\"Ver archivos\"</b> o <b>\"Guardar cambios\"</b>.",
    btn_confirm: "Continuar y Elegir Carpeta",
    save_title: "Guardar Espacio de Trabajo en Disco",
    save_p1: "Tus datos están actualmente almacenados con seguridad en la memoria local (RAM). Para hacerlos permanentes, selecciona la carpeta de trabajo en tu PC.",
    save_box_title: "Cómo proceder:",
    save_step_existing: "<b>Si ya tenías un Espacio de Trabajo:</b> selecciona tu carpeta de trabajo habitual para actualizarla con los cambios actuales de la sesión.",
    save_step_new: "<b>Si es un nuevo archivo:</b> selecciona una carpeta dedicada en tu disco duro.",
    save_step_permissions: "Cuando el navegador solicite confirmación de permisos, haz clic en <b>\"Ver archivos\"</b> o <b>\"Guardar cambios\"</b>.",
    btn_save_confirm: "Elegir Carpeta y Guardar",
    confirm_update_existing_ws: "La carpeta seleccionada ya contiene un Espacio de Trabajo de VanillaDesk.\n\n¿Deseas conectarla y guardar aquí las modificaciones actuales de la sesión?",
    confirm_folder_not_empty: "Atención: La carpeta seleccionada contiene otros archivos.\nLa aplicación guardará las notas y las bases de datos en su interior. ¿Deseas continuar?"
},
modpack_guide: {
    title: "Qué es un Modpack y cómo funciona",
    p1: "Un <b>Modpack</b> es un paquete autónomo y compartible en formato JSON que reúne una nota completa junto con todos sus componentes avanzados (Bases de datos relacionales, tableros Kanban, fórmulas, gráficos y botones Macro).",
    p2: "La instalación es <b>completamente segura y no destructiva</b>: se creará una nueva nota en tu Espacio de Trabajo y todos los identificadores de bases de datos se regenerarán para no sobrescribir jamás tus datos existentes.",
    box_title: "Qué hacer ahora:",
    step1: "Haz clic en <b>\"Continuar y Elegir Archivo\"</b> a continuación.",
    step2: "Selecciona el archivo <code>.json</code> del Modpack guardado en tu ordenador.",
    step3: "Confirma la vista previa del paquete para integrarlo instantáneamente en tu espacio de trabajo.",
    btn_confirm: "Continuar y Elegir Archivo"
},
